//! `splot-capi` - the C ABI of the splot streaming AV2 decoder.
//!
//! The API follows dav1d: open a decoder, send one temporal unit at a time,
//! take pictures, drain at end of stream, close. A picture's plane pointers
//! point into the decoder's own sample storage; no sample is copied. The
//! header is `include/splot.h`, generated by cbindgen.
//!
//! One decoder takes calls from one thread at a time. A picture can be
//! released on any thread. [`splot_apply_grain`] needs no decoder: it runs on
//! any thread and after [`splot_close`], but not while another thread
//! releases the same picture.
//!
//! Every `unsafe` block here relies only on the `# Safety` contract of the
//! function it is in: the caller passes null or valid pointers, and each
//! boxed handle goes back to Rust exactly once.
//!
//! Feature tracking: `CAPI-DECODER-ABI`.
//!
//! Licensed under PolyForm Noncommercial 1.0.0; commercial use requires a
//! separate written license from Bartosz Tomczyk.

#![allow(
    unsafe_code,
    reason = "the C ABI dereferences caller pointers; each block states its contract"
)]

mod atlas;
pub use atlas::*;

use core::ffi::{c_char, c_int, c_void};
use core::num::NonZeroUsize;
use core::ptr;

use splot_core::headers::content_interpretation::DerivedColorInfo;
use splot_core::types::ExtendedLayerId;
use splot_decode::{
    BitDepth, DataProps, Decoder, DecoderSettings, EmbeddedLayerSelection, ExtendedLayerSelection,
    ExternalAtlases, FrameDelay, FrameType, ObuLocation, OperatingPointSelection, Picture,
    PictureProvenance, PictureSamples, PixelFormat, PlaneId, PlaneRef, SendStatus,
    TemporalLayerSelection, ThreadCount,
};

/// The call succeeded.
pub const SPLOT_OK: c_int = 0;
/// [`splot_send_data`]: the decoder is full; take pictures, then send the
/// same data again. [`splot_get_picture`] and [`splot_wait_picture`]: send
/// more data first.
pub const SPLOT_EAGAIN: c_int = -1;
/// [`splot_get_picture`]: the decoder is drained; no picture follows.
pub const SPLOT_EOF: c_int = -2;
/// An argument was null or out of range.
pub const SPLOT_EINVAL: c_int = -3;
/// The bitstream failed to decode, or a resource limit stopped it. The
/// decoder takes no more data; flush or close it. [`splot_apply_grain`]: the synthesis
/// failed; no decoder is affected.
pub const SPLOT_EDECODE: c_int = -4;
/// The decoder takes no more data until [`splot_flush`]: it is draining, or
/// it failed earlier.
pub const SPLOT_ESTATE: c_int = -5;

/// An open decoder.
pub struct SplotDecoder {
    decoder: Decoder,
    drained: bool,
}

/// Settings for [`splot_open`] and [`splot_open_with_atlases`]. Fill them with
/// [`splot_default_settings`] first.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct SplotSettings {
    /// Worker threads; 0 picks one per logical core.
    pub n_threads: u32,
    /// Frames decoded in parallel; 0 picks a value from `n_threads`. 1 is
    /// lowest latency.
    pub max_frame_delay: u32,
    /// 1 leaves film grain out of the pictures; [`splot_apply_grain`] adds it
    /// to a picture later. 0 applies it.
    pub skip_film_grain: u8,
    /// Bitmask (`1..=15`) of temporal layers (`1 << temporal_layer_id`) to emit;
    /// transitive dependencies still decode. `0` emits all layers (default).
    pub temporal_output_mask: u8,
    /// Bitmask (`1..=255`) of embedded layers (`1 << embedded_layer_id`) to emit;
    /// transitive dependencies still decode. `0` emits all layers (default).
    pub embedded_output_mask: u8,
    /// Reserved; keep zero.
    pub reserved0: u8,
    /// Bitmask (`1..=0x7fffffff`) of extended layers (`1 << extended_layer_id`) to emit.
    /// `0` emits all extended layers (default). Bit 31 (`0x80000000`) is invalid.
    pub extended_output_mask: u32,
    /// Operating-point selection scope: `0` = none (default), `1` = global OPS,
    /// `2` = local OPS on `operating_point_xlayer_id`. Cannot be non-zero when
    /// any output mask is non-zero.
    pub operating_point_scope: u8,
    /// Target extended layer (`0..=30`) when `operating_point_scope == 2`; keep zero otherwise.
    pub operating_point_xlayer_id: u8,
    /// `ops_id` (`0..=15`) when `operating_point_scope != 0`; keep zero otherwise.
    pub operating_point_ops_id: u8,
    /// Operating-point index (`0..=6`) when `operating_point_scope != 0`; keep zero otherwise.
    pub operating_point_index: u8,
    /// Reserved; keep zero.
    pub reserved: [u8; 20],
}

/// Caller data that goes with one temporal unit to the pictures it codes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct SplotDataProps {
    /// Presentation timestamp, in the caller's time base.
    pub pts: i64,
    /// Duration, in the caller's time base.
    pub duration: i64,
    /// An opaque caller value.
    pub user_data: u64,
}

/// Chroma layout of a picture.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SplotPixelLayout {
    /// Luma only.
    I400 = 0,
    /// 4:2:0.
    I420 = 1,
    /// 4:2:2.
    I422 = 2,
    /// 4:4:4.
    I444 = 3,
}

/// The values of [`SplotPicture::frame_type`].
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SplotFrameType {
    /// A zeroed picture, or a frame whose type the decoder did not derive.
    None = 0,
    /// A closed-loop or open-loop key frame.
    Key = 1,
    /// An inter frame.
    Inter = 2,
    /// An intra-only frame.
    IntraOnly = 3,
    /// A switch frame.
    Switch = 4,
}

/// Color description of a picture, from AV2 § 5.15 content interpretation.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct SplotColor {
    /// Color primaries code point.
    pub primaries: u8,
    /// Transfer characteristics code point.
    pub transfer: u8,
    /// Matrix coefficients code point.
    pub matrix: u8,
    /// 1 for full range, 0 for limited range.
    pub full_range: u8,
}

/// An OBU location in one temporal unit.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SplotObuLocation {
    /// The `SplotDataProps.user_data` value of the unit.
    pub user_data: u64,
    /// The byte offset from the start of the unit to the OBU header after its length prefix.
    pub offset: u64,
}

impl From<ObuLocation> for SplotObuLocation {
    fn from(value: ObuLocation) -> Self {
        Self {
            user_data: value.user_data,
            offset: value.offset.get(),
        }
    }
}

/// The AV2 input locations for a decoded picture.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SplotPictureProvenance {
    /// The frame OBU that coded the samples. This is the first tile group for a tiled frame.
    pub coded: SplotObuLocation,
    /// The frame OBU that caused display. This is `coded` unless a show-existing OBU caused display.
    pub display: SplotObuLocation,
    /// The sequence header in effect when the decoder decoded the coded frame.
    pub sequence_header: SplotObuLocation,
}

impl From<PictureProvenance> for SplotPictureProvenance {
    fn from(value: PictureProvenance) -> Self {
        Self {
            coded: value.coded.into(),
            display: value.display.into(),
            sequence_header: value.sequence_header.into(),
        }
    }
}

/// A decoded picture. Valid from [`splot_get_picture`] or
/// [`splot_apply_grain`] until [`splot_picture_unref`].
#[repr(C)]
#[derive(Debug)]
pub struct SplotPicture {
    /// Y, U and V planes at their first stored sample, 64-byte aligned.
    /// The visible area starts `crop_top` rows and `crop_left` samples in
    /// (both shifted right by the chroma subsampling for U and V). 8-bit
    /// pictures hold one byte per sample, 10-bit pictures one `uint16_t` per
    /// sample in the low bits. U and V are null for [`SplotPixelLayout::I400`].
    pub data: [*const c_void; 3],
    /// Bytes from one row to the next, for each plane; a multiple of 64.
    pub stride: [isize; 3],
    /// Visible width in luma samples.
    pub width: u32,
    /// Visible height in luma samples.
    pub height: u32,
    /// Luma samples between the left of `data` and the visible area.
    pub crop_left: u32,
    /// Luma rows between the top of `data` and the visible area.
    pub crop_top: u32,
    /// Bits per sample: 8 or 10.
    pub bit_depth: u32,
    /// Chroma layout.
    pub layout: SplotPixelLayout,
    /// Color description.
    pub color: SplotColor,
    /// The caller data of the unit that coded or showed this picture.
    pub props: SplotDataProps,
    /// 1 when the stream signals film grain for this picture, whether or not
    /// `skip_film_grain` left it out; else 0.
    pub has_film_grain: u8,
    /// A [`SplotFrameType`] value: the type of the frame this picture shows.
    pub frame_type: u8,
    /// Temporal layer ID (`obu_tlayer_id`, `0..=3`) of the output picture.
    /// A show-existing frame with a derived order hint uses the reference layer ID.
    pub temporal_layer_id: u8,
    /// Embedded layer ID (`obu_mlayer_id`, `0..=7`) of the output picture.
    /// A show-existing frame with a derived order hint uses the reference layer ID.
    pub embedded_layer_id: u8,
    /// Extended layer id (`obu_xlayer_id`, `0..=30`) of the picture.
    pub extended_layer_id: u8,
    /// Immutable atlas snapshot. Null when the picture has no atlas association.
    pub atlas: *const SplotPictureAtlas,
    /// Number of associations accessible through `splot_atlas_info`.
    pub atlas_count: usize,
    /// Immutable input locations. The picture owns this data until `splot_picture_unref`.
    pub provenance: *const SplotPictureProvenance,
    /// The decoder's handle on the samples; do not touch.
    pub internal: *mut c_void,
}

/// The library version as a NUL-terminated string.
#[unsafe(no_mangle)]
pub extern "C" fn splot_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

/// Fills `settings` with the defaults.
///
/// # Safety
/// `settings` is null or points to writable memory for one [`SplotSettings`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_default_settings(settings: *mut SplotSettings) {
    if let Some(settings) = unsafe { settings.as_mut() } {
        *settings = SplotSettings {
            n_threads: 0,
            max_frame_delay: 0,
            skip_film_grain: 0,
            temporal_output_mask: 0,
            embedded_output_mask: 0,
            reserved0: 0,
            extended_output_mask: 0,
            operating_point_scope: 0,
            operating_point_xlayer_id: 0,
            operating_point_ops_id: 0,
            operating_point_index: 0,
            reserved: [0; 20],
        };
    }
}

/// Opens a decoder and stores it in `*out`.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EINVAL`] for a null argument, a
/// `skip_film_grain` above 1, `temporal_output_mask` above `15`, invalid
/// operating-point settings, or nonzero reserved bytes, or [`SPLOT_EDECODE`]
/// when the worker pool cannot start.
///
/// # Safety
/// `out` is null or writable; `settings` is null or points to a
/// [`SplotSettings`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_open(
    out: *mut *mut SplotDecoder,
    settings: *const SplotSettings,
) -> c_int {
    let (Some(out), Some(settings)) = (unsafe { out.as_mut() }, unsafe { settings.as_ref() })
    else {
        return SPLOT_EINVAL;
    };
    open_decoder(out, settings, ExternalAtlases::default())
}

fn open_decoder(
    out: &mut *mut SplotDecoder,
    settings: &SplotSettings,
    atlases: ExternalAtlases,
) -> c_int {
    *out = ptr::null_mut();
    if settings.skip_film_grain > 1
        || settings.temporal_output_mask > 0x0F
        || settings.reserved0 != 0
        || (settings.extended_output_mask & (1u32 << 31)) != 0
        || settings.reserved.iter().any(|&byte| byte != 0)
    {
        return SPLOT_EINVAL;
    }
    let has_output_masks = settings.temporal_output_mask != 0
        || settings.embedded_output_mask != 0
        || settings.extended_output_mask != 0;
    let operating_point_selection = match settings.operating_point_scope {
        0 => {
            if settings.operating_point_xlayer_id != 0
                || settings.operating_point_ops_id != 0
                || settings.operating_point_index != 0
            {
                return SPLOT_EINVAL;
            }
            OperatingPointSelection::None
        }
        1 => {
            if has_output_masks
                || settings.operating_point_xlayer_id != 0
                || settings.operating_point_ops_id > 15
                || settings.operating_point_index > 6
            {
                return SPLOT_EINVAL;
            }
            OperatingPointSelection::Global {
                ops_id: settings.operating_point_ops_id,
                op_index: settings.operating_point_index,
            }
        }
        2 => {
            if has_output_masks
                || settings.operating_point_xlayer_id > 30
                || settings.operating_point_ops_id > 15
                || settings.operating_point_index > 6
            {
                return SPLOT_EINVAL;
            }
            OperatingPointSelection::Local {
                xlayer_id: ExtendedLayerId::from_bits(settings.operating_point_xlayer_id),
                ops_id: settings.operating_point_ops_id,
                op_index: settings.operating_point_index,
            }
        }
        _ => return SPLOT_EINVAL,
    };
    let temporal_selection = if settings.temporal_output_mask != 0 {
        TemporalLayerSelection::OutputMask(settings.temporal_output_mask)
    } else {
        TemporalLayerSelection::All
    };
    let embedded_selection = if settings.embedded_output_mask != 0 {
        EmbeddedLayerSelection::OutputMask(settings.embedded_output_mask)
    } else {
        EmbeddedLayerSelection::All
    };
    let extended_selection = if settings.extended_output_mask != 0 {
        ExtendedLayerSelection::OutputMask(settings.extended_output_mask)
    } else {
        ExtendedLayerSelection::All
    };
    let count = |value: u32| NonZeroUsize::new(value as usize);
    let settings = DecoderSettings::default()
        .with_threads(count(settings.n_threads).map_or(ThreadCount::Auto, ThreadCount::Fixed))
        .with_frame_delay(
            count(settings.max_frame_delay)
                .map_or(FrameDelay::Auto, |depth| FrameDelay::from(depth.get())),
        )
        .with_skip_film_grain(settings.skip_film_grain == 1)
        .with_temporal_layer_selection(temporal_selection)
        .with_embedded_layer_selection(embedded_selection)
        .with_extended_layer_selection(extended_selection)
        .with_operating_point_selection(operating_point_selection);
    match Decoder::new_with_external_atlases(settings, atlases) {
        Ok(decoder) => {
            *out = Box::into_raw(Box::new(SplotDecoder {
                decoder,
                drained: false,
            }));
            SPLOT_OK
        }
        Err(_) => SPLOT_EDECODE,
    }
}

/// Sends one whole temporal unit of `size` bytes. The decoder copies it.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EAGAIN`] when the decoder is full,
/// [`SPLOT_EINVAL`], [`SPLOT_EDECODE`] or [`SPLOT_ESTATE`].
///
/// # Safety
/// `decoder` is null or points to an open decoder. `data` points to `size`
/// readable bytes (it may be null when `size` is 0); `props` is null or
/// points to a [`SplotDataProps`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_send_data(
    decoder: *mut SplotDecoder,
    data: *const u8,
    size: usize,
    props: *const SplotDataProps,
) -> c_int {
    let Some(SplotDecoder { decoder, .. }) = (unsafe { decoder.as_mut() }) else {
        return SPLOT_EINVAL;
    };
    // SAFETY: The caller keeps the input readable for this call.
    let Some(data) = (unsafe { borrowed_slice(data, size) }) else {
        return SPLOT_EINVAL;
    };
    let props = unsafe { props.as_ref() }.copied().unwrap_or_default();
    let props = DataProps::default()
        .with_pts(props.pts)
        .with_duration(props.duration)
        .with_user_data(props.user_data);
    match decoder.send_data(data, props) {
        Ok(SendStatus::Accepted) => SPLOT_OK,
        Ok(SendStatus::Full) => SPLOT_EAGAIN,
        Err(error) => error_code(&error),
    }
}

/// # Safety
/// For a nonempty slice, the caller supplies one live, readable array of
/// `count` initialized elements. Its bytes must remain immutable during the borrow.
unsafe fn borrowed_slice<'a, T>(data: *const T, count: usize) -> Option<&'a [T]> {
    if count == 0 {
        return Some(&[]);
    }
    if data.is_null()
        || !data.is_aligned()
        || count.checked_mul(size_of::<T>())? > isize::MAX as usize
    {
        return None;
    }
    // SAFETY: The checks cover alignment and size. The caller guarantees the array.
    Some(unsafe { core::slice::from_raw_parts(data, count) })
}

/// Ends the input; [`splot_get_picture`] then returns the remaining pictures
/// and [`SPLOT_EOF`].
///
/// # Safety
/// `decoder` is null or points to an open decoder.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_drain(decoder: *mut SplotDecoder) {
    if let Some(SplotDecoder { decoder, drained }) = unsafe { decoder.as_mut() } {
        decoder.drain();
        *drained = true;
    }
}

/// Drops every unit and picture the decoder holds and starts a new session
/// on the same threads, for a seek or after [`SPLOT_EDECODE`]. Decoding
/// starts again at a temporal unit with a sequence header and a closed-loop
/// key, open-loop key or RAS frame.
/// Pictures already taken stay valid until released.
///
/// # Safety
/// `decoder` is null or points to an open decoder.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_flush(decoder: *mut SplotDecoder) {
    if let Some(SplotDecoder { decoder, drained }) = unsafe { decoder.as_mut() } {
        decoder.flush();
        *drained = false;
    }
}

/// Takes the next picture in display order into `*out`.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EAGAIN`] when more data is needed,
/// [`SPLOT_EOF`] after the last picture of a drained decoder,
/// [`SPLOT_EINVAL`] or [`SPLOT_EDECODE`]. On any result but [`SPLOT_OK`],
/// `*out` is zeroed.
///
/// # Safety
/// `decoder` is null or points to an open decoder. `out` is null or points to a
/// zeroed or released picture: this call overwrites `*out`, so a picture in
/// `*out` that was not released with [`splot_picture_unref`] leaks.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_get_picture(
    decoder: *mut SplotDecoder,
    out: *mut SplotPicture,
) -> c_int {
    unsafe { take_picture(decoder, out, Decoder::get_picture) }
}

/// [`splot_get_picture`], but waits until the data sent so far is decoded:
/// [`SPLOT_EAGAIN`] then means that data gives no further picture yet.
///
/// # Safety
/// As [`splot_get_picture`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_wait_picture(
    decoder: *mut SplotDecoder,
    out: *mut SplotPicture,
) -> c_int {
    unsafe { take_picture(decoder, out, Decoder::wait_picture) }
}

/// # Safety
/// As [`splot_get_picture`].
unsafe fn take_picture(
    decoder: *mut SplotDecoder,
    out: *mut SplotPicture,
    take: fn(&mut Decoder) -> splot_decode::Result<Option<Picture>>,
) -> c_int {
    let (Some(SplotDecoder { decoder, drained }), Some(out)) =
        (unsafe { decoder.as_mut() }, unsafe { out.as_mut() })
    else {
        return SPLOT_EINVAL;
    };
    *out = empty_picture();
    match take(decoder) {
        Ok(Some(picture)) => {
            *out = c_picture(picture);
            SPLOT_OK
        }
        Ok(None) if *drained => SPLOT_EOF,
        Ok(None) => SPLOT_EAGAIN,
        Err(error) => error_code(&error),
    }
}

/// Stores in `*out` the picture `picture` with the film grain of AV2 § 7.21.7
/// applied. A picture that has its grain, or whose stream signals none,
/// shares its samples with `*out`. `picture` stays valid; release both.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EINVAL`] for a null argument, a zeroed
/// picture or `out` equal to `picture`, or [`SPLOT_EDECODE`] when the
/// synthesis fails. On [`SPLOT_EDECODE`], `*out` is zeroed.
///
/// # Safety
/// `picture` is null or points to a picture from [`splot_get_picture`] or
/// this function that was not released yet, or to a zeroed picture. `out` is
/// null or points to a zeroed or released picture: this call overwrites
/// `*out`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_apply_grain(
    out: *mut SplotPicture,
    picture: *const SplotPicture,
) -> c_int {
    if out.is_null() || picture.is_null() || ptr::eq(out, picture) {
        return SPLOT_EINVAL;
    }
    let Some(source) = (unsafe { (*picture).internal.cast::<SplotPictureAtlas>().as_ref() }) else {
        return SPLOT_EINVAL;
    };
    let (grained, code) = match source.picture.apply_film_grain() {
        Ok(grained) => (c_picture(grained), SPLOT_OK),
        Err(_) => (empty_picture(), SPLOT_EDECODE),
    };
    unsafe { out.write(grained) };
    code
}

/// Releases a picture from [`splot_get_picture`] or [`splot_apply_grain`] and
/// zeroes it.
///
/// # Safety
/// `picture` is null or points to a picture from one of those calls that was
/// not released yet, or to a zeroed picture.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_picture_unref(picture: *mut SplotPicture) {
    let Some(picture) = (unsafe { picture.as_mut() }) else {
        return;
    };
    let internal = core::mem::replace(picture, empty_picture()).internal;
    if !internal.is_null() {
        drop(unsafe { Box::from_raw(internal.cast::<SplotPictureAtlas>()) });
    }
}

/// Closes a decoder and sets `*decoder` to null. Pictures already taken stay
/// valid until released.
///
/// # Safety
/// `decoder` is null or points to a null handle or an open decoder handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_close(decoder: *mut *mut SplotDecoder) {
    let Some(decoder) = (unsafe { decoder.as_mut() }) else {
        return;
    };
    let owned = core::mem::replace(decoder, ptr::null_mut());
    if !owned.is_null() {
        drop(unsafe { Box::from_raw(owned) });
    }
}

fn error_code(error: &splot_decode::DecodeError) -> c_int {
    match error {
        splot_decode::DecodeError::State { .. } => SPLOT_ESTATE,
        _ => SPLOT_EDECODE,
    }
}

const fn empty_picture() -> SplotPicture {
    SplotPicture {
        data: [ptr::null(); 3],
        stride: [0; 3],
        width: 0,
        height: 0,
        crop_left: 0,
        crop_top: 0,
        bit_depth: 0,
        layout: SplotPixelLayout::I400,
        color: SplotColor {
            primaries: 0,
            transfer: 0,
            matrix: 0,
            full_range: 0,
        },
        props: SplotDataProps {
            pts: 0,
            duration: 0,
            user_data: 0,
        },
        has_film_grain: 0,
        frame_type: SplotFrameType::None as u8,
        temporal_layer_id: 0,
        embedded_layer_id: 0,
        extended_layer_id: 0,
        atlas: ptr::null(),
        atlas_count: 0,
        provenance: ptr::null(),
        internal: ptr::null_mut(),
    }
}

fn c_picture(picture: Picture) -> SplotPicture {
    let mut out = empty_picture();
    for (index, plane) in [PlaneId::Y, PlaneId::U, PlaneId::V].into_iter().enumerate() {
        (out.data[index], out.stride[index]) = match picture.plane(plane) {
            Some(PictureSamples::Eight(plane)) => storage_origin(plane),
            Some(PictureSamples::Ten(plane)) => storage_origin(plane),
            None => (ptr::null(), 0),
        };
    }
    let color = picture
        .content_interpretation()
        .map_or(DerivedColorInfo::UNSPECIFIED, |content| {
            content.derived_color()
        });
    let props = picture.props();
    out.width = picture.width() as u32;
    out.height = picture.height() as u32;
    let crop = match picture.plane(PlaneId::Y) {
        Some(PictureSamples::Eight(luma)) => Some(luma.visible_rect()),
        Some(PictureSamples::Ten(luma)) => Some(luma.visible_rect()),
        None => None,
    };
    out.crop_left = crop.map_or(0, |crop| crop.x() as u32);
    out.crop_top = crop.map_or(0, |crop| crop.y() as u32);
    out.bit_depth = match picture.bit_depth() {
        BitDepth::Eight => 8,
        BitDepth::Ten => 10,
    };
    out.layout = match picture.pixel_format() {
        PixelFormat::Monochrome => SplotPixelLayout::I400,
        PixelFormat::Yuv420 => SplotPixelLayout::I420,
        PixelFormat::Yuv422 => SplotPixelLayout::I422,
        PixelFormat::Yuv444 => SplotPixelLayout::I444,
    };
    out.color = SplotColor {
        primaries: color.code_points.color_primaries,
        transfer: color.code_points.transfer_characteristics,
        matrix: color.code_points.matrix_coefficients,
        full_range: u8::from(color.full_range),
    };
    out.props = SplotDataProps {
        pts: props.pts,
        duration: props.duration,
        user_data: props.user_data,
    };
    out.has_film_grain = u8::from(picture.has_film_grain());
    out.frame_type = match picture.frame_type() {
        Some(FrameType::Key) => SplotFrameType::Key,
        Some(FrameType::Inter) => SplotFrameType::Inter,
        Some(FrameType::IntraOnly) => SplotFrameType::IntraOnly,
        Some(FrameType::Switch) => SplotFrameType::Switch,
        _ => SplotFrameType::None,
    } as u8;
    out.temporal_layer_id = picture.temporal_layer_id().get();
    out.embedded_layer_id = picture.embedded_layer_id().get();
    out.extended_layer_id = picture.extended_layer_id().get();
    out.atlas_count = picture.atlas_associations().len();
    let handle = Box::into_raw(Box::new(SplotPictureAtlas {
        provenance: picture.provenance().into(),
        picture,
    }));
    out.provenance = handle
        .wrapping_byte_add(core::mem::offset_of!(SplotPictureAtlas, provenance))
        .cast();
    if out.atlas_count != 0 {
        out.atlas = handle;
    }
    out.internal = handle.cast();
    out
}

/// The address of `plane`'s first stored sample and its stride in bytes.
fn storage_origin<T: splot_decode::ReconSample>(plane: PlaneRef<'_, T>) -> (*const c_void, isize) {
    (
        plane.samples().as_ptr().cast(),
        (plane.stride_samples() * size_of::<T>()) as isize,
    )
}
